// Todos os limites ficam reunidos aqui para facilitar ajustes futuros.
return [{
  json: {
    limite_critico: 0.15,
    limite_atencao: 0.30,
    limite_doadora: 0.80,
    limite_lotacao: 0.90,
    reserva_doadora: 0.40,
    alvo_destino: 0.50,
    transferencia_minima: 2,
    transferencia_maxima: 8,
    distancia_maxima_km: 8,
    fuso_horario: 'America/Bahia'
  }
}];

// Reúne o cadastro das estações com a posição atual e aplica as regras operacionais.
const config = $('Parâmetros do projeto').first().json;
const cadastros = $('Consultar cadastro das estações').first().json.data?.stations || [];
const posicoes = $input.first().json.data?.stations || [];

if (!cadastros.length || !posicoes.length) {
  throw new Error('A API não devolveu as listas de estações no formato esperado.');
}

function textoLocalizado(valor) {
  if (typeof valor === 'string') return valor;
  if (!Array.isArray(valor) || !valor.length) return 'Estação sem nome';
  const portugues = valor.find(item => item.language === 'pt' || item.language === 'pt-BR');
  return (portugues || valor[0]).text || 'Estação sem nome';
}

function distanciaKm(lat1, lon1, lat2, lon2) {
  const raio = 6371;
  const rad = graus => graus * Math.PI / 180;
  const dLat = rad(lat2 - lat1);
  const dLon = rad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(dLon / 2) ** 2;
  return raio * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function classificar(ocupacao) {
  if (ocupacao <= config.limite_critico) return 'Crítica';
  if (ocupacao < config.limite_atencao) return 'Atenção';
  if (ocupacao > config.limite_lotacao) return 'Risco de lotação';
  if (ocupacao > config.limite_doadora) return 'Excesso';
  return 'Equilibrada';
}

const cadastroPorId = new Map(cadastros.map(item => [String(item.station_id), item]));

const estacoes = posicoes.map(posicao => {
  const id = String(posicao.station_id);
  const cadastro = cadastroPorId.get(id) || {};
  const capacidade = Number(cadastro.capacity) || 0;
  const bicicletas = Number(posicao.num_vehicles_available) || 0;
  const vagas = Number(posicao.num_docks_available) || 0;
  const operacional = Boolean(posicao.is_installed) && Boolean(posicao.is_renting) && Boolean(posicao.is_returning) && capacidade > 0;
  const ocupacao = capacidade > 0 ? bicicletas / capacidade : 0;

  return {
    station_id: id,
    nome: textoLocalizado(cadastro.name),
    latitude: Number.isFinite(Number(cadastro.lat)) ? Number(cadastro.lat) : null,
    longitude: Number.isFinite(Number(cadastro.lon)) ? Number(cadastro.lon) : null,
    capacidade,
    bicicletas,
    vagas,
    operacional,
    ocupacao,
    ocupacao_pct: Number((ocupacao * 100).toFixed(1)),
    classificacao: operacional ? classificar(ocupacao) : 'Indisponível'
  };
});

const operacionais = estacoes.filter(estacao => estacao.operacional);
const destinos = operacionais
  .filter(estacao => estacao.ocupacao <= config.limite_critico)
  .sort((a, b) => a.ocupacao - b.ocupacao || a.bicicletas - b.bicicletas);

const doadoras = operacionais
  .filter(estacao => estacao.ocupacao > config.limite_doadora)
  .map(estacao => ({
    ...estacao,
    saldo_disponivel: Math.max(0, estacao.bicicletas - Math.ceil(estacao.capacidade * config.reserva_doadora))
  }));

const agora = new Date();
const partes = new Intl.DateTimeFormat('en-CA', {
  timeZone: config.fuso_horario, year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(agora);
const partesData = Object.fromEntries(partes.map(parte => [parte.type, parte.value]));
const dataLocal = `${partesData.year}-${partesData.month}-${partesData.day}`;
const momento = agora.toISOString();
const execucaoId = `bike_salvador_${momento.replace(/[-:.TZ]/g, '').slice(0, 14)}`;
const ordens = [];

for (const destino of destinos) {
  const necessidade = Math.max(0, Math.ceil(destino.capacidade * config.alvo_destino) - destino.bicicletas);

  const candidatas = doadoras
    .filter(doadora => doadora.station_id !== destino.station_id)
    .filter(doadora => doadora.saldo_disponivel >= config.transferencia_minima)
    .filter(doadora => doadora.latitude !== null && doadora.longitude !== null)
    .filter(() => destino.latitude !== null && destino.longitude !== null)
    .map(doadora => ({
      doadora,
      distancia: distanciaKm(doadora.latitude, doadora.longitude, destino.latitude, destino.longitude)
    }))
    .filter(candidata => candidata.distancia <= config.distancia_maxima_km)
    .sort((a, b) => a.distancia - b.distancia);

  if (!candidatas.length || necessidade < config.transferencia_minima) continue;

  const escolhida = candidatas[0];
  const quantidade = Math.min(necessidade, escolhida.doadora.saldo_disponivel, config.transferencia_maxima);
  if (quantidade < config.transferencia_minima) continue;

  escolhida.doadora.saldo_disponivel -= quantidade;
  const prioridade = destino.bicicletas === 0 ? 'Crítica' : destino.ocupacao <= 0.10 ? 'Alta' : 'Média';

  ordens.push({
    chave_ordem: `${dataLocal}_${escolhida.doadora.station_id}_${destino.station_id}`,
    criada_em: momento,
    origem_id: escolhida.doadora.station_id,
    origem: escolhida.doadora.nome,
    destino_id: destino.station_id,
    destino: destino.nome,
    quantidade,
    distancia_km: Number(escolhida.distancia.toFixed(2)),
    prioridade,
    motivo: destino.bicicletas === 0 ? 'Estação sem bicicletas disponíveis' : `Estação com apenas ${destino.ocupacao_pct}% de ocupação`,
    status: 'Pendente',
    origem_ocupacao_pct: escolhida.doadora.ocupacao_pct,
    destino_ocupacao_pct: destino.ocupacao_pct,
    execucao_id: execucaoId
  });
}

const contar = classificacao => operacionais.filter(estacao => estacao.classificacao === classificacao).length;
const bicicletasSugeridas = ordens.reduce((total, ordem) => total + ordem.quantidade, 0);
const mensagem = ordens.length
  ? `${ordens.length} ordens sugeridas, movimentando ${bicicletasSugeridas} bicicletas.`
  : 'Nenhuma ordem foi necessária com os parâmetros atuais.';

const resumo = {
  execucao_id: execucaoId,
  executada_em: momento,
  total_estacoes: estacoes.length,
  estacoes_operacionais: operacionais.length,
  criticas: contar('Crítica'),
  atencao: contar('Atenção'),
  equilibradas: contar('Equilibrada'),
  excesso: contar('Excesso'),
  risco_lotacao: contar('Risco de lotação'),
  ordens_sugeridas: ordens.length,
  bicicletas_sugeridas: bicicletasSugeridas,
  mensagem
};

return [{
  json: {
    resumo,
    ordens,
    log_execucao: { ...resumo, fonte: 'GBFS Bike Itaú Salvador' },
    estacoes_criticas: destinos.slice(0, 10).map(estacao => ({
      station_id: estacao.station_id,
      nome: estacao.nome,
      bicicletas: estacao.bicicletas,
      capacidade: estacao.capacidade,
      ocupacao_pct: estacao.ocupacao_pct
    }))
  }
}];

// Cada ordem vira um item separado para ser registrada na fila operacional.
const ordens = $input.first().json.ordens || [];
return ordens.map(ordem => ({ json: ordem }));

// Consolida os principais indicadores para acompanhamento da execução.
const entrada = $input.first().json;
return [{
  json: {
    ...entrada.resumo,
    estacoes_criticas: entrada.estacoes_criticas
  }
}];
